.nl-d{margin:12px 0 0;color:#d0d6e0;font:15px/1.55 Montserrat,system-ui,sans-serif;max-width:46ch}
.nl-form{margin:0;font-family:Montserrat,system-ui,sans-serif}
.nl-row{display:flex;gap:10px}
.nl-form input[type=email]{flex:1 1 auto;min-width:0;height:48px;box-sizing:border-box;padding:0 16px;border-radius:8px;border:1px solid rgba(255,255,255,.14);background:rgba(255,255,255,.04);color:#f7f8f8;font:16px Montserrat,system-ui,sans-serif}
.nl-form input[type=email]::placeholder{color:#8a8f98}
.nl-form input[type=email]:focus{outline:none;border-color:#009a44;box-shadow:0 0 0 3px rgba(0,154,68,.25)}
.nl-form input[aria-invalid=true]{border-color:#ff3d33}
.nl-form button[type=submit]{flex:0 0 auto;height:48px;padding:0 22px;border:0;border-radius:8px;background:#009a44;color:#fff;font:600 14px Montserrat,system-ui,sans-serif;letter-spacing:.02em;cursor:pointer}
.nl-form button[type=submit]:hover{background:#00b350}
.nl-form button[type=submit]:focus-visible{outline:2px solid #fff;outline-offset:2px}
.nl-form button[disabled]{opacity:.6;cursor:default}
.nl-msg{margin:10px 0 0;font-size:14px;font-weight:600;min-height:0}
.nl-msg:empty{display:none}
.nl-msg.ok{color:#34c46a} .nl-msg.err{color:#ff3d33}
.nl-note{margin:10px 0 0;font-size:12.5px;color:#8a8f98}
.nl-note a{color:#d0d6e0;text-underline-offset:3px}
.nl-form.done .nl-row,.nl-form.done .nl-note{display:none}
.nl-form.done .nl-msg{margin-top:0;font-size:16px}
/* footer band */
.nl-band{border-bottom:0}
.nl-wrap{max-width:1200px;margin:0 auto;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px))}
.nl-band-in{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:24px 48px;align-items:center;padding-block:40px}
@media (max-width:820px){.nl-band-in{grid-template-columns:minmax(0,1fr);padding-block:40px}}
@media (max-width:480px){.nl-band .nl-row{flex-direction:column}.nl-band .nl-form button[type=submit]{width:100%}}
/* pop-up */
#nl-pop[hidden]{display:none}
#nl-pop{position:fixed;inset:0;z-index:2147483647 !important;display:flex;align-items:center;justify-content:center;padding:16px}
#nl-pop .nl-back{position:absolute;inset:0;background:rgba(0,0,0,.6);backdrop-filter:blur(2px)}
#nl-pop .nl-box{position:relative;width:100%;max-width:460px;box-sizing:border-box;background:#0f1011;border:1px solid rgba(255,255,255,.14);border-top:3px solid #009a44;border-radius:12px;padding:32px 28px 26px;box-shadow:0 24px 60px rgba(0,0,0,.6);outline:none;animation:nlIn .25s ease-out}
#nl-pop .nl-d{margin-bottom:20px}
#nl-pop .nl-x{position:absolute;top:10px;right:10px;width:40px;height:40px;display:grid;place-items:center;border:0;border-radius:8px;background:transparent;cursor:pointer}
#nl-pop .nl-x svg{width:20px;height:20px;fill:none;stroke:#d0d6e0;stroke-width:2;stroke-linecap:round}
#nl-pop .nl-x:hover{background:rgba(255,255,255,.06)} #nl-pop .nl-x:focus-visible{outline:2px solid #009a44}
@keyframes nlIn{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}
@media (max-width:640px){
  #nl-pop{align-items:flex-end;padding:0}
  #nl-pop .nl-back{background:rgba(0,0,0,.35);backdrop-filter:none}
  #nl-pop .nl-box{max-width:none;border-radius:16px 16px 0 0;border-left:0;border-right:0;border-bottom:0;padding:26px 16px calc(20px + env(safe-area-inset-bottom,0px))}
  #nl-pop .nl-t{font-size:28px;padding-right:40px}
  #nl-pop .nl-d{font-size:14px;margin-bottom:16px}
  #nl-pop .nl-row{flex-direction:column} #nl-pop .nl-form button[type=submit]{width:100%}
}
@media (prefers-reduced-motion:reduce){#nl-pop .nl-box{animation:none}}
