<script>
(function(){
  var URL='https://c20401b9.sibforms.com/serve/MUIFACJOu7ccgvzQx0Os6Ufdk7qgrrQshoPPXrCqUL3B6oEQ3ZH8GYNYsXln9tQ-g7SSytfQLolkvE5ZqLO1uADraBt1sZCRx6kQblp5154MNVlZl7Iy9x6MyrcorkvpSaaksa6KFnVDBLc8HlZMfGEnMbXcEFbgvKVKkFFEQYKm0kCexECB51T1wepBk1_8yIoblC3zdbT1bQ9g?isAjax=1';
  var K='cc_nl', DELAY=25000, MINSCROLL=10000, SNOOZE=30*864e5;
  function get(){try{return JSON.parse(localStorage.getItem(K)||'{}')||{};}catch(e){return {};}}
  function set(o){try{localStorage.setItem(K,JSON.stringify(o));}catch(e){}}
  var pop=document.getElementById('nl-pop'), lastFocus=null, timer=null;

  /* forms (footer + pop-up) */
  document.querySelectorAll('form.nl-form').forEach(function(f){
    var em=f.querySelector('input[type=email]'), msg=f.querySelector('.nl-msg'), btn=f.querySelector('button[type=submit]');
    em.addEventListener('input',function(){em.removeAttribute('aria-invalid');if(msg.classList.contains('err')){msg.textContent='';msg.className='nl-msg';}});
    f.addEventListener('submit',function(e){
      e.preventDefault();
      var v=em.value.trim();
      if(!v||!em.checkValidity()){em.setAttribute('aria-invalid','true');msg.className='nl-msg err';msg.textContent='Please enter a valid email address.';em.focus();return;}
      if(f.querySelector('[name=email_address_check]').value){return;}
      var fd=new FormData();fd.append('EMAIL',v);fd.append('email_address_check','');fd.append('locale','en');
      btn.disabled=true;btn.textContent='Sending…';
      fetch(URL,{method:'POST',body:fd}).then(function(r){return r.json();}).then(function(d){
        if(!d||!d.success){throw new Error('fail');}
        f.classList.add('done');msg.className='nl-msg ok';msg.textContent='Thanks, you’re subscribed! Watch your inbox for our next update.';
        set({s:1});
        try{if(typeof gtag==='function'){gtag('event','sign_up',{method:'newsletter'});}if(window.fbq){fbq('track','Lead');}}catch(x){}
        if(pop&&!pop.hidden&&pop.contains(f)){setTimeout(close,3500);}
      }).catch(function(){
        msg.className='nl-msg err';msg.textContent='Sorry, that didn’t work. Please try again.';
      }).then(function(){btn.disabled=false;btn.textContent='Subscribe';});
    });
  });

  /* pop-up */
  if(!pop){return;}
  function open(){
    lastFocus=document.activeElement;pop.hidden=false;
    pop.querySelector('.nl-box').focus({preventScroll:true});
    document.addEventListener('keydown',onKey);
  }
  function close(){
    if(pop.hidden){return;}
    pop.hidden=true;document.removeEventListener('keydown',onKey);
    var st=get();if(!st.s){set({c:Date.now()});}
    if(lastFocus&&lastFocus.focus){try{lastFocus.focus({preventScroll:true});}catch(e){}}
  }
  function onKey(e){
    if(e.key==='Escape'){close();return;}
    if(e.key==='Tab'){
      var els=[].slice.call(pop.querySelectorAll('button,input:not(.nl-hp),a[href]')).filter(function(x){return x.offsetParent!==null;});
      if(!els.length){return;}
      var a=els[0],z=els[els.length-1];
      if(e.shiftKey&&(document.activeElement===a||document.activeElement===pop.querySelector('.nl-box'))){e.preventDefault();z.focus();}
      else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a.focus();}
    }
  }
  pop.querySelectorAll('[data-nl-close]').forEach(function(b){b.addEventListener('click',close);});

  var st=get();
  if(st.s){return;}
  if(st.c&&Date.now()-st.c<SNOOZE){return;}
  if(/^\/(contact|tools)(\/|$)/.test(location.pathname)){return;}
  var t0;try{t0=+sessionStorage.getItem('cc_nl_t0');if(!t0){t0=Date.now();sessionStorage.setItem('cc_nl_t0',t0);}}catch(e){t0=Date.now();}
  var halfway=false;
  window.addEventListener('scroll',function(){
    var h=document.documentElement.scrollHeight-innerHeight;
    if(h>0&&scrollY/h>=0.5){halfway=true;}
  },{passive:true});
  function ready(){
    var c=null;try{c=localStorage.getItem('cc_consent');}catch(e){c='x';}
    if(!c){return false;}
    var b=document.getElementById('cc-consent');if(b&&!b.hidden){return false;}
    var a=document.activeElement;if(a&&/^(INPUT|TEXTAREA|SELECT)$/.test(a.tagName)){return false;}
    return true;
  }
  timer=setInterval(function(){
    var t=Date.now()-t0;
    if((t>=DELAY||(halfway&&t>=MINSCROLL))&&ready()){clearInterval(timer);open();}
  },1000);
})();
</script>
